import unittest
from solution import validate_schema

class TestSchemaValidator(unittest.TestCase):
    def setUp(self):
        self.user_schema = {
            "type": "dict",
            "required": ["name", "age"],
            "properties": {
                "name": {"type": "string"},
                "age": {"type": "number"},
                "active": {"type": "boolean"}
            }
        }

    def test_valid(self):
        valid_data = {"name": "Alice", "age": 30, "active": True}
        ok, errors = validate_schema(valid_data, self.user_schema)
        self.assertTrue(ok)
        self.assertEqual(len(errors), 0)

    def test_missing_required(self):
        invalid_data = {"name": "Bob"}
        ok, errors = validate_schema(invalid_data, self.user_schema)
        self.assertFalse(ok)
        self.assertTrue(any("age" in err for err in errors))

    def test_type_mismatch(self):
        # In Python bool is subclass of int; boolean must not match number!
        invalid_data = {"name": "Charlie", "age": True}
        ok, errors = validate_schema(invalid_data, self.user_schema)
        self.assertFalse(ok)

if __name__ == '__main__':
    unittest.main()
